fn main() {
    // Declaring the app commands makes tauri-build auto-generate
    // `permissions/autogenerated/allow-*.toml` files for each command.
    // Without them, the app's ACL manifest has no entries for the commands,
    // and Tauri REJECTS invokes from remote/local webviews with
    // "Command ... not allowed by ACL".
    tauri_build::try_build(tauri_build::Attributes::new().app_manifest(
        tauri_build::AppManifest::new().commands(&[
            "open_external_url",
            "prepare_download_folder",
            "download_media",
            "save_media_bytes",
            "report_dm_unread",
            "test_message_notification",
            "open_downloader_window",
            "take_pending_downloader_context",
            "inspect_instagram_post",
            "submit_downloader_probe",
            "download_post_selection",
            "save_caption_file",
            "open_downloads_folder",
        ]),
    ))
    .expect("failed to run tauri-build");
}
